import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 3

def design(feats):
    # Identify strong candidates by mean difference and t-test
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for now
        mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
        t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        strong_candidates.append((fid, abs(mean_diff), abs(t_stat)))

    strong_candidates.sort(key=lambda x: x[2], reverse=True)

    # Remove near-duplicates based on correlation
    keep = set()
    correlated_pairs = set()
    for i in range(len(strong_candidates)):
        fid1 = strong_candidates[i][0]
        for j in range(i+1, len(strong_candidates)):
            fid2 = strong_candidates[j][0]
            if abs(np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]) >= 0.6:
                correlated_pairs.add((fid1, fid2))

    # Keep only one from each correlated pair
    for fid, _, _ in strong_candidates:
        if all(not (fid == f1 or fid == f2) or (f1, f2) not in correlated_pairs for f1, f2 in correlated_pairs):
            keep.add(fid)

    # Try product terms between top candidates
    candidates = [fid for fid in keep if feats.types[feats.column(fid)] != 'clinical']
    if len(candidates) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check for product terms
    best_product = None
    best_score = -np.inf
    for i in range(min(5, len(candidates))):
        for j in range(i+1, min(5, len(candidates))):
            fid1, fid2 = candidates[i], candidates[j]
            prod = feats.x[:, feats.column(fid1)] * feats.x[:, feats.column(fid2)]
            t_stat, _ = stats.ttest_ind(prod[feats.y==1], prod[feats.y==0])
            if abs(t_stat) > best_score:
                best_score = abs(t_stat)
                best_product = (fid1, fid2)

    # If we found a good product term, use it
    if best_product and best_score > 4.0:
        return Design(
            drivers=(best_product[0], best_product[1]),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={best_product[0]: 1.0, best_product[1]: 1.0}
        )

    # Otherwise, return empty design
    return Design(drivers=(), columns=(), products=(), loadings={})

